yp0 and name ~= \034\034 and not ident:match(\034^JS:\034) then\010    local typ = typ0:gsub(\034i$\034, \034\034)\010    local short = name:gsub(\034%s*%b()%s*$\034, \034\034)\010    add(typ0 .. \034:\034 .. name)\010    add(typ .. \034: \034 .. name)\010    add(typ .. \034:\034 .. name)\010    add(name)\010    if short ~= \034\034 and short ~= name then\010      add(typ .. \034: \034 .. short)\010      add(typ .. \034:\034 .. short)\010      add(short)\010    end\010  end\010  return out\010end\010local function pshelf_add(is_track, target, ident, quiet)\010  if not target or not ident or ident == \034\034 then return -1 end\010  local count = is_track and reaper.TrackFX_GetCount or reaper.TakeFX_GetCount\010  local chain_vis = is_track and reaper.TrackFX_GetChainVisible or reaper.TakeFX_GetChainVisible\010  local show = is_track and reaper.TrackFX_Show or reaper.TakeFX_Show\010  local ok_cv, vis0 = pcall(chain_vis, target)\010  local before = count(target)\010  local idx = -1\010  for _, v in ipairs(pshelf_variants(ident)) do\010    local ok, i\010    if is_track then ok, i = pcall(reaper.TrackFX_AddByName, target, v, false, 1)\010    else ok, i = pcall(reaper.TakeFX_AddByName, target, v, 1) end\010    if ok and i and i >= 0 then idx = i; break end\010    if count(target) > before then idx = before; break end\010  end\010  local after = count(target)\010  if after > before then\010    local ok_st, st = pcall(reaper.GetToggleCommandStateEx, 0, 41078)\010    local float_on = (not quiet) and ok_st and st == 1\010    for k = before, after - 1 do pcall(show, target, k, float_on and 3 or 2) end\010    if not float_on and ok_cv and vis0 == -1 then\010      local ok_cv2, vis1 = pcall(chain_vis, target)\010      if ok_cv2 and vis1 ~= -1 then pcall(show, target, before, 0) end\010    end\010  end\010  return idx\010end\010\004\005load\004%\010return pshelf_add, pshelf_chain_rel\004\014=pshelf_fxadd\004\002t\004\013setmetatable\004\008__index\004\003_G\004\007fx_add\004\010